SELECT 'jobs' AS metric, jsonb_build_object('total', count(*), 'active',count(*) FILTER (WHERE "isActive"), 'public',count(*) FILTER (WHERE "isActive" AND "mergedIntoId" IS NULL AND "withdrawnAt" IS NULL), 'active_no_raw',count(*) FILTER (WHERE "isActive" AND raw IS NULL), 'merged',count(*) FILTER(WHERE "mergedIntoId" IS NOT NULL), 'closed',count(*) FILTER(WHERE "closedAt" IS NOT NULL), 'withdrawn',count(*) FILTER(WHERE "withdrawnAt" IS NOT NULL), 'latestSeen',max("lastSeenAt"),'oldestActiveSeen',min("lastSeenAt") FILTER(WHERE "isActive"),'activeSeenBefore48h', count(*) FILTER (WHERE "isActive" AND "lastSeenAt"<now()-interval '48 hours'),'activePastValidThrough',count(*) FILTER(WHERE "isActive" AND "validThrough"<now())) AS value FROM "Job"
UNION ALL SELECT 'sources', jsonb_object_agg(status,n) FROM (SELECT status,count(*) n FROM "Source" GROUP BY status) x
UNION ALL SELECT 'jobSources',jsonb_build_object('total',count(*),'active',count(*) FILTER(WHERE "isActive"),'raw',count(raw),'sourceKeys',count(DISTINCT "sourceKey")) FROM "JobSource"
UNION ALL SELECT 'observations',jsonb_build_object('total',count(*),'sourceKeys',count(DISTINCT "sourceKey"),'latest',max("observedAt")) FROM "SourceObservation"
UNION ALL SELECT 'database',jsonb_build_object('size',pg_database_size(current_database()),'version',version())
UNION ALL SELECT 'runs_7d',jsonb_object_agg(status,n) FROM (SELECT status,count(*) n FROM "SourceRun" WHERE "ranAt">now()-interval '7 days' GROUP BY status) x;
